function collectFees(
        IERC20 tokenX,
        IERC20 tokenY,
        uint16 binStep,
        uint256[] calldata ids,
        address to
    ) external override returns (uint256 amountX, uint256 amountY) {
        ILBPair lbPair = ILBPair(_getLBPairInformation(tokenX, tokenY, binStep));

        (uint128 collectedX, uint128 collectedY) = lbPair.collectFees(ids, to);

        amountX = uint256(collectedX);
        amountY = uint256(collectedY);
    }

function collectFeesBatch(
        FeeCollectionParameters[] calldata feeCollectionParameters
    ) external override returns (uint256[] memory amountsX, uint256[] memory amountsY) {
        uint256 length = feeCollectionParameters.length;
        amountsX = new uint256[](length);
        amountsY = new uint256[](length);

        for (uint256 i = 0; i < length;) {
            FeeCollectionParameters calldata params = feeCollectionParameters[i];
            ILBPair lbPair = ILBPair(_getLBPairInformation(params.tokenX, params.tokenY, params.binStep));

            (uint128 collectedX, uint128 collectedY) = lbPair.collectFees(params.ids, params.to);

            amountsX[i] = uint256(collectedX);
            amountsY[i] = uint256(collectedY);

            unchecked {
                ++i;
            }
        }
    }

function collectFeesNATIVE(
        IERC20 token,
        uint16 binStep,
        uint256[] calldata ids,
        address payable to
    ) external override returns (uint256 amountToken, uint256 amountNATIVE) {
        ILBPair lbPair = ILBPair(_getLBPairInformation(token, IERC20(_wnative), binStep));

        (uint128 collectedX, uint128 collectedY) = lbPair.collectFees(ids, address(this));

        bool isNATIVETokenY = IERC20(_wnative) == lbPair.getTokenY();

        if (isNATIVETokenY) {
            amountToken = uint256(collectedX);
            amountNATIVE = uint256(collectedY);

            _safeTransfer(token, to, amountToken);
            _wNativeWithdrawAndTransfer(to, amountNATIVE);
        } else {
            amountToken = uint256(collectedY);
            amountNATIVE = uint256(collectedX);

            _safeTransfer(token, to, amountToken);
            _wNativeWithdrawAndTransfer(to, amountNATIVE);
        }
    }

function collectRewards(
        IERC20 tokenX,
