function mintPosition(IHandler _handler, bytes calldata _mintPositionData)
        external
        onlyWhitelistedHandlers(_handler)
        nonReentrant
        returns (uint256 sharesMinted)
    {
        uint256 tokenId = _handler.getHandlerIdentifier(_mintPositionData);

        (address[] memory tokens, uint256[] memory amounts) = _handler.tokensToPullForMint(_mintPositionData);

        uint256 amount;
        for (uint256 i; i < tokens.length; i++) {
            amount = amounts[i];
            if (amount != 0) {
                IERC20(tokens[i]).safeTransferFrom(msg.sender, address(this), amount);
                IERC20(tokens[i]).safeIncreaseAllowance(address(_handler), amount);
            }
        }

        sharesMinted = _handler.mintPositionHandler(msg.sender, _mintPositionData);

        emit LogMintPosition(_handler, tokenId, msg.sender, sharesMinted);
    }

function burnPosition(IHandler _handler, bytes calldata _burnPositionData)
        external
        onlyWhitelistedHandlers(_handler)
        nonReentrant
        returns (uint256 sharesBurned)
    {
        uint256 tokenId = _handler.getHandlerIdentifier(_burnPositionData);

        sharesBurned = _handler.burnPositionHandler(msg.sender, _burnPositionData);

        emit LogBurnPosition(_handler, tokenId, msg.sender, sharesBurned);
    }

function mintPositionHandler(address context, bytes calldata _mintPositionData) external returns (uint256) {
        onlyWhitelisted();

        (MintPositionParams memory _params, bytes memory hookData) =
            abi.decode(_mintPositionData, (MintPositionParams, bytes));

        if (hookPerms[_params.hook].onMint && hookRegistered[_params.hook]) {
            IHook(_params.hook).onMintBefore(hookData);
        }

        (uint128 liquidity,,) = mintInternal(
            MintLiquidityInternalCache({
                self: false,
                tokenId: uint256(
                    keccak256(abi.encode(address(this), _params.pool, _params.hook, _params.tickLower, _params.tickUpper))
                ),
                pool: _params.pool,
                hook: _params.hook,
                liquidity: _params.liquidity,
                amount0: 0,
                amount1: 0,
                tickLower: _params.tickLower,
                tickUpper: _params.tickUpper,
                context: context
            })
        );

        return liquidity;
    }

function burnPositionHandler(address context, bytes calldata _burnPositionData) external returns (uint256) {
        onlyWhitelisted();

        (BurnPositionParams memory _params, bytes memory hookData) =
            abi.decode(_burnPositionData, (BurnPositionParams, bytes));

        if (hookPerms[_params.hook].onBurn && hookRegistered[_params.hook]) {
            IHook(_params.hook).onBurnBefore(hookData);
        }

        burnInternal(
            BurnLiquidityInternalCache({
                tokenId: uint256(
                    keccak256(abi.encode(address(this), _params.pool, _params.hook, _params.tickLower, _params.tickUpper))
                ),
                pool: _params.pool,
                hook: _params.hook,
                tickLower: _params.tickLower,
                tickUpper: _params.tickUpper,
                liquidity: _params.liquidity,
                context: context,
                receiver: context
            })
        );

        return _params.liquidity;
    }

function addLiquidity(AddLiquidityParams memory params)
        public
        returns (uint128 liquidity, uint256 amount0, uint256 amount1, IUniswapV3Pool pool)
    {
        PoolKey memory poolKey = PoolKey({token0: params.token0, token1: params.token1, fee: params.fee});

        pool = IUniswapV3Pool(computeAddress(factory, poolKey));

        // compute the liquidity amount
        {
            (uint160 sqrtPriceX96,,,,,,) = pool.slot0();
            uint160 sqrtRatioAX96 = TickMath.getSqrtRatioAtTick(params.tickLower);
            uint160 sqrtRatioBX96 = TickMath.getSqrtRatioAtTick(params.tickUpper);

            liquidity = LiquidityAmounts.getLiquidityForAmounts(
                sqrtPriceX96, sqrtRatioAX96, sqrtRatioBX96, params.amount0Desired, params.amount1Desired
            );
        }

        (amount0, amount1) = pool.mint(
            params.recipient,
            params.tickLower,
            params.tickUpper,
            liquidity,
            abi.encode(MintCallbackData({poolKey: poolKey, payer: msg.sender}))
        );
    }

